g2("08", "이차함수의 그래프와 삼각형의 넓이", SEC.일반형, "심화하", (rng) =>
  attempt(300, (): Body | null => {
    const a = pick(rng, [1, -1, 2, -2] as const);
    const r1 = intBetween(rng, -5, 1);
    const r2 = r1 + pick(rng, [2, 4, 6] as const);
    if (Math.abs(r2) > 6) return null;
    if (r1 === 0 || r2 === 0) return null; // y절편이 0 이면 삼각형이 안 생긴다
    const A = rInt(a);
    const B = rInt(-a * (r1 + r2));
    const C = rInt(a * r1 * r2);
    const p = (r1 + r2) / 2;
    if (!Number.isInteger(p)) return null;
    // 꼭짓점 y좌표 — y=a(x-r1)(x-r2) 의 꼭짓점은 (p, -a(r2-r1)^2/4) 이다.
    const vy = -(a * (r2 - r1) * (r2 - r1)) / 4;
    if (!Number.isInteger(vy)) return null;
    const fig = parabolaFig(rInt(a), p, vy, [
      [r1, 0],
      [r2, 0],
      [0, C[0]],
    ]);
    if (fig === null) return null;
    const area = (Math.abs(r2 - r1) * Math.abs(C[0])) / 2;
    if (!Number.isInteger(area)) return null;
    return {
      content: `오른쪽 그림과 같이 이차함수 $y=${genRhs(A, B, C)}$의 그래프가 $x$축과 두 점 $\\mathrm{A}$, $\\mathrm{B}$에서 만나고 $y$축과 점 $\\mathrm{C}$에서 만난다. 삼각형 $\\mathrm{ABC}$의 넓이를 구하시오.`,
      answer: `$${area}$`,
      solution: `$y=0$${eulReul(0)} 대입하면 $x=${r1}$ 또는 $x=${r2}$이므로 $\\mathrm{A}${pt(r1, 0)}$, $\\mathrm{B}${pt(r2, 0)}$이다.\n$x=0$${eulReul(0)} 대입하면 $y=${C[0]}$이므로 $\\mathrm{C}(0, ${C[0]})$이다.\n밑변의 길이는 $${r2 - r1}$, 높이는 $${Math.abs(C[0])}$이므로 넓이는 $\\dfrac{1}{2}\\times${r2 - r1}\\times${Math.abs(C[0])}=${area}$이다.`,

g2("01", "이차함수 를 의 꼴로 고치기", SEC.일반형, "기본", (rng) =>
  attempt(60, (): Body | null => {
    const a = pick(rng, A_INT);
    const p = intBetween(rng, 1, 5) * pick(rng, SIGNS);
    const q = intBetween(rng, -9, 9);
    const { A, B, C } = expand(rInt(a), p, q);
    if (Math.abs(C[0]) > 60) return null;
    return {
      content: `이차함수 $y=${genRhs(A, B, C)}$${C[0] !== 0 ? eulReul(C[0]) : B[0] !== 0 ? "를" : "을"} $y=a(x-p)^2+q$ 꼴로 나타내시오. (단, $a$, $p$, $q$는 상수이다.)`,
      answer: `$y=${stdRhs(rInt(a), p, q)}$`,
      solution: toStdLines(a, p, q).join("\n"),
      facts: { a, p, q, A: A[0], B: B[0], C: C[0] },
      figureSpec: null,
    };
  }),
),

g2("02", "이차함수 의 그래프의 꼭짓점과 축", SEC.일반형, "기본", (rng) =>
  attempt(60, (): Body | null => {
    const a = pick(rng, A_INT);
    const p = intBetween(rng, 1, 5) * pick(rng, SIGNS);
    const q = intBetween(rng, -9, 9);
    const { A, B, C } = expand(rInt(a), p, q);
    if (Math.abs(C[0]) > 60) return null;
    const mode = intBetween(rng, 0, 1);
    if (mode === 0) {
      return {
        content: `이차함수 $y=${genRhs(A, B, C)}$의 그래프의 꼭짓점의 좌표와 축의 방정식을 차례로 구하시오.`,
        answer: `$${pt(p, q)}$, $x=${p}$`,
        solution: `${toStdLines(a, p, q).join("\n")}\n따라서 꼭짓점의 좌표는 $${pt(p, q)}$이고 축의 방정식은 $x=${p}$이다.`,
        facts: { mode, a, p, q, C: C[0] },
        figureSpec: null,
      };
    }
    return {
      content: `이차함수 $y=${genRhs(A, B, C)}$의 그래프의 꼭짓점의 좌표를 $(s, t)$, 축의 방정식을 $x=k$라 할 때, $s+t+k$의 값을 구하시오.`,
      answer: `$${2 * p + q}$`,
      solution: `${toStdLines(a, p, q).join("\n")}\n꼭짓점의 좌표는 $${pt(p, q)}$이고 축의 방정식은 $x=${p}$이므로 $s=${p}$, $t=${q}$, $k=${p}$이다.\n따라서 $s+t+k=${2 * p + q}$이다.`,
      facts: { mode, a, p, q, C: C[0], ans: 2 * p + q },
      figureSpec: null,
    };
  }),
),

g2("05", "이차함수의 그래프와 축축과의 교점", SEC.일반형, "응용", (rng) =>
  attempt(120, (): Body | null => {
    // 근을 먼저 고른다 — 판별식이 제곱수라 근호가 지면에 안 나간다.
    const a = pick(rng, [1, -1, 2, -2] as const);
    const r1 = intBetween(rng, -5, 2);
    const r2 = r1 + intBetween(rng, 2, 7);
    if (Math.abs(r2) > 6) return null;
    const A = rInt(a);
    const B = rInt(-a * (r1 + r2));
    const C = rInt(a * r1 * r2);
    const mode = intBetween(rng, 0, 1);
    if (mode === 0) {
      return {
        content: `이차함수 $y=${genRhs(A, B, C)}$의 그래프가 $x$축과 만나는 두 점을 각각 $\\mathrm{A}$, $\\mathrm{B}$라 할 때, 선분 $\\mathrm{AB}$의 길이를 구하시오.`,
        answer: `$${r2 - r1}$`,
        solution: `$y=0$${eulReul(0)} 대입하면 $${genRhs(A, B, C)}=0$이고, 좌변을 인수분해하면 $${factoredTex(A, r1, r2)}=0$이다.\n즉 $x=${r1}$ 또는 $x=${r2}$이므로 두 점의 좌표는 $${pt(r1, 0)}$, $${pt(r2, 0)}$이다.\n따라서 선분 $\\mathrm{AB}$의 길이는 $${r2}-${baseTex(r1)}=${r2 - r1}$이다.`,
        facts: { mode, a, r1, r2, B: B[0], C: C[0], ans: r2 - r1 },
        figureSpec: null,
      };
    }
    return {
      content: `이차함수 $y=${genRhs(A, B, C)}$의 그래프가 $x$축과 만나는 두 점 중 한 점의 좌표가 $${pt(r1, 0)}$일 때, 다른 한 점의 좌표를 구하시오.`,
      answer: `$${pt(r2, 0)}$`,
      solution: `$y=0$${eulReul(0)} 대입하여 좌변을 인수분해하면 $${factoredTex(A, r1, r2)}=0$이다.\n즉 $x=${r1}$ 또는 $x=${r2}$이다.\n따라서 다른 한 점의 좌표는 $${pt(r2, 0)}$이다.`,
      facts: { mode, a, r1, r2, B: B[0], C: C[0] },
      figureSpec: null,
    };
  }),
),

g2(
  "10",
  "이차함수의 식 구하기 꼭짓점과 다른 한 점을 알 때",
  SEC.일반형,
  "응용",
  (rng) =>
    attempt(60, (): Body | null => {
      const a = pick(rng, A_INT);
      const p = intBetween(rng, -4, 4);
      const q = intBetween(rng, -8, 8);
      const s = pick(rng, [-3, -2, -1, 1, 2, 3] as const);
      const m = p + s;
      const v = a * s * s + q;
      if (Math.abs(v) > 40) return null;
      const { A, B, C } = expand(rInt(a), p, q);
      if (Math.abs(C[0]) > 60) return null;
      return {
        content: `꼭짓점의 좌표가 $${pt(p, q)}$이고 점 $${pt(m, v)}$${eulReul(v)} 지나는 포물선을 그래프로 하는 이차함수의 식을 $y=ax^2+bx+c$ 꼴로 나타내시오. (단, $a$, $b$, $c$는 상수이다.)`,
        answer: `$y=${genRhs(A, B, C)}$`,
        solution: `꼭짓점의 좌표가 $${pt(p, q)}$이므로 구하는 식을 $y=a${sqTex(p)}${termTex(rInt(q), "")}$ 꼴로 놓는다.\n$x=${m}$, $y=${v}$${eulReul(v)} 대입하면 $${termTex(rInt(s * s), "a", true)}${termTex(rInt(q), "")}=${v}$이므로 $a=${a}$이다.\n따라서 $y=${stdEqGen(stdRhs(rInt(a), p, q), genRhs(A, B, C))}$이다.`,
        facts: { a, p, q, m, v, A: A[0], B: B[0], C: C[0] },
        figureSpec: null,
      };
    }),
),

g2(
  "11",
  "이차함수의 식 구하기 축의 방정식과 두 점을 알 때",
  SEC.일반형,
  "응용",
  (rng) =>
    attempt(60, (): Body | null => {
      const a = pick(rng, A_INT);
      const p = intBetween(rng, -3, 3);
      const q = intBetween(rng, -8, 8);
      const s1 = pick(rng, [-3, -2, -1] as const);
      const s2 = pick(rng, [1, 2, 3] as const);
      // ⚠️ 두 점이 **축에 대칭**이면(|s1|=|s2|) 대입한 두 식이 글자까지 같아진다.
      //    조건이 하나뿐이므로 $a$ 가 안 정해지고 **답이 무수히 많다** — 그런데
      //    적힌 답도 조건을 만족하니 **값 검사는 통과한다.** 9가지 중 3가지라
      //    실측 33.3% 가 그랬다(2026-08-24). `probe-middle-uniqueness.ts` 가 잡아 준다.
      if (s1 * s1 === s2 * s2) return null;
      const m1 = p + s1;
      const m2 = p + s2;
      const v1 = a * s1 * s1 + q;
      const v2 = a * s2 * s2 + q;
      if (Math.abs(v1) > 40 || Math.abs(v2) > 40) return null;
      const { A, B, C } = expand(rInt(a), p, q);
      if (Math.abs(C[0]) > 60) return null;
      return {
        content: `축의 방정식이 $x=${p}$이고 두 점 $${pt(m1, v1)}$, $${pt(m2, v2)}$${eulReul(v2)} 지나는 포물선을 그래프로 하는 이차함수의 식을 $y=ax^2+bx+c$ 꼴로 나타내시오. (단, $a$, $b$, $c$는 상수이다.)`,
        answer: `$y=${genRhs(A, B, C)}$`,
        solution: `축의 방정식이 $x=${p}$이므로 구하는 식을 $y=a${sqTex(p)}+q$로 놓는다.\n두 점의 좌표를 대입하면 $${termTex(rInt(s1 * s1), "a", true)}+q=${v1}$, $${termTex(rInt(s2 * s2), "a", true)}+q=${v2}$이다.\n두 식을 연립하여 풀면 $a=${a}$, $q=${q}$이다.\n따라서 $y=${stdEqGen(stdRhs(rInt(a), p, q), genRhs(A, B, C))}$이다.`,
        facts: { a, p, q, m1, v1, m2, v2, A: A[0], B: B[0], C: C[0] },
        figureSpec: null,
      };
    }),
),

g2(
  "12",
  "이차함수의 식 구하기 서로 다른 세 점을 알 때",
  SEC.일반형,
  "응용",
  (rng) =>
    attempt(60, (): Body | null => {
      const a = pick(rng, A_INT);
      const p = intBetween(rng, -3, 3);
      const q = intBetween(rng, -8, 8);
      const { A, B, C } = expand(rInt(a), p, q);
      if (Math.abs(C[0]) > 40) return null;
      const x1 = pick(rng, [-3, -2, -1] as const);
      const x2 = pick(rng, [1, 2, 3] as const);
      const f = (x: number): number => a * (x - p) * (x - p) + q;
      const y1 = f(x1);
      const y2 = f(x2);
      if (Math.abs(y1) > 40 || Math.abs(y2) > 40) return null;
      return {
        content: `세 점 $(0, ${C[0]})$, $${pt(x1, y1)}$, $${pt(x2, y2)}$${eulReul(y2)} 지나는 포물선을 그래프로 하는 이차함수의 식을 $y=ax^2+bx+c$ 꼴로 나타내시오. (단, $a$, $b$, $c$는 상수이다.)`,
        answer: `$y=${genRhs(A, B, C)}$`,
        solution: `구하는 식을 $y=ax^2+bx+c$로 놓는다.\n점 $(0, ${C[0]})$${eulReul(C[0])} 지나므로 $c=${C[0]}$이다.\n나머지 두 점을 대입하면 $${termTex(rInt(x1 * x1), "a", true)}${termTex(rInt(x1), "b")}${termTex(C, "")}=${y1}$, $${termTex(rInt(x2 * x2), "a", true)}${termTex(rInt(x2), "b")}${termTex(C, "")}=${y2}$이다.\n두 식을 연립하여 풀면 $a=${A[0]}$, $b=${B[0]}$이다.\n따라서 $y=${genRhs(A, B, C)}$이다.`,
        facts: { a, p, q, x1, y1, x2, y2, A: A[0], B: B[0], C: C[0] },
        figureSpec: null,
      };
    }),
),

g2(
  "13",
  "이차함수의 식 구하기 축과의 두 교점과 다른 한 점을 알 때",
  SEC.일반형,
  "응용",
  (rng) =>
    attempt(120, (): Body | null => {
      const a = pick(rng, A_INT);
      const r1 = intBetween(rng, -5, 1);
      const r2 = r1 + intBetween(rng, 2, 6);
      if (Math.abs(r2) > 5) return null;
      const m = pick(rng, [
        r1 - 1,
        r2 + 1,
        (r1 + r2) % 2 === 0 ? (r1 + r2) / 2 : r2 + 2,
      ] as const);
      if (m === r1 || m === r2) return null;
      const v = a * (m - r1) * (m - r2);
      if (Math.abs(v) > 40 || v === 0) return null;
      const A = rInt(a);
      const B = rInt(-a * (r1 + r2));
      const C = rInt(a * r1 * r2);
      if (Math.abs(C[0]) > 60) return null;
      return {
        content: `$x$축과 두 점 $${pt(r1, 0)}$, $${pt(r2, 0)}$에서 만나고 점 $${pt(m, v)}$${eulReul(v)} 지나는 포물선을 그래프로 하는 이차함수의 식을 $y=ax^2+bx+c$ 꼴로 나타내시오. (단, $a$, $b$, $c$는 상수이다.)`,
        answer: `$y=${genRhs(A, B, C)}$`,
        solution: `$x$축과 두 점 $${pt(r1, 0)}$, $${pt(r2, 0)}$에서 만나므로 구하는 식을 $y=${factoredWithA(r1, r2)}$${r2 === 0 ? "로" : euroRo(r2)} 놓는다.\n$x=${m}$, $y=${v}$${eulReul(v)} 대입하면 $${termTex(rInt((m - r1) * (m - r2)), "a", true)}=${v}$이므로 $a=${a}$이다.\n따라서 $y=${genRhs(A, B, C)}$이다.`,
        facts: { a, r1, r2, m, v, A: A[0], B: B[0], C: C[0] },
        figureSpec: null,
      };
    }),
),

g2(
  "19",
  "이차함수의 활용 도형의 넓이",
  SEC.최대최소,
  "심화하",
  (rng): Body => {
    const h = intBetween(rng, 3, 14);
    const mode = intBetween(rng, 0, 2);
    if (mode === 0) {
      return {
        content: `둘레의 길이가 $${4 * h}\\,\\mathrm{cm}$인 직사각형의 넓이의 최댓값을 구하시오.`,
        answer: `$${h * h}\\,\\mathrm{cm}^2$`,
        solution: `가로의 길이를 $x\\,\\mathrm{cm}$라 하면 세로의 길이는 $(${2 * h}-x)\\,\\mathrm{cm}$이다.\n넓이를 $y\\,\\mathrm{cm}^2$라 하면 $y=x(${2 * h}-x)=-(x-${h})^2+${h * h}$이다.\n따라서 $x=${h}$일 때 넓이의 최댓값은 $${h * h}\\,\\mathrm{cm}^2$이다.`,
        facts: { mode, h, ans: h * h },
        figureSpec: null,
      };
    }
    if (mode === 1) {
      return {
        content: `가로와 세로의 길이의 합이 $${2 * h}\\,\\mathrm{cm}$인 직사각형 중에서 넓이가 가장 큰 것의 가로의 길이를 구하시오.`,
        answer: `$${h}\\,\\mathrm{cm}$`,
        solution: `가로의 길이를 $x\\,\\mathrm{cm}$라 하면 세로의 길이는 $(${2 * h}-x)\\,\\mathrm{cm}$이다.\n넓이를 $y\\,\\mathrm{cm}^2$라 하면 $y=-(x-${h})^2+${h * h}$이다.\n따라서 넓이가 가장 클 때의 가로의 길이는 $${h}\\,\\mathrm{cm}$이다.`,
        facts: { mode, h, ans: h },
        figureSpec: null,
      };
    }
    const s = 2 * h;
    return {
      content: `한 변의 길이가 $${s}\\,\\mathrm{cm}$인 정사각형 $\\mathrm{ABCD}$에서 점 $\\mathrm{P}$는 변 $\\mathrm{AB}$ 위를, 점 $\\mathrm{Q}$는 변 $\\mathrm{AD}$ 위를 움직이고 $\\overline{\\mathrm{AP}}=\\overline{\\mathrm{DQ}}$이다. 삼각형 $\\mathrm{APQ}$의 넓이의 최댓값을 구하시오.`,
      answer: `$${(h * h) / 2}\\,\\mathrm{cm}^2$`,
      solution: `$\\overline{\\mathrm{AP}}=x\\,\\mathrm{cm}$라 하면 $\\overline{\\mathrm{DQ}}=x\\,\\mathrm{cm}$이므로 $\\overline{\\mathrm{AQ}}=(${s}-x)\\,\\mathrm{cm}$이다.\n삼각형 $\\mathrm{APQ}$의 넓이를 $y\\,\\mathrm{cm}^2$라 하면 $y=\\dfrac{1}{2}x(${s}-x)=-\\dfrac{1}{2}(x-${h})^2+${(h * h) / 2}$이다.\n따라서 $x=${h}$일 때 넓이의 최댓값은 $${(h * h) / 2}\\,\\mathrm{cm}^2$이다.`,
      facts: { mode, h, ans: (h * h) / 2 },
      figureSpec: null,
    };
  },
),

g2(
  "21",
  "이차함수의 활용 내접하는 도형의 넓이",
  SEC.최대최소,
  "심화하",
  (rng): Body => {
    const mode = intBetween(rng, 0, 2);
    if (mode === 0) {
      const h = intBetween(rng, 2, 9);
      const b = 2 * h;
      return {
        content: `직선 $y=-x+${b}$ 위에 있는 제$1$사분면 위의 점 $\\mathrm{P}$에서 $x$축, $y$축에 내린 수선의 발을 각각 $\\mathrm{Q}$, $\\mathrm{R}$라 할 때, 직사각형 $\\mathrm{OQPR}$의 넓이의 최댓값을 구하시오. (단, $\\mathrm{O}$는 원점이다.)`,
        answer: `$${h * h}$`,
        solution: `점 $\\mathrm{P}$의 좌표를 $(x, -x+${b})$${eulReul(b) === "을" ? "이라" : "라"} 하면 $\\overline{\\mathrm{OQ}}=x$, $\\overline{\\mathrm{PQ}}=-x+${b}$이다.\n넓이를 $y$라 하면 $y=x(-x+${b})=-(x-${h})^2+${h * h}$이다.\n따라서 $x=${h}$일 때 넓이의 최댓값은 $${h * h}$이다.`,
        facts: { mode, b, h, ans: h * h },
        figureSpec: null,
      };
    }
    if (mode === 1) {
      const m = pick(rng, [2, 4] as const);
      const h = intBetween(rng, 1, 5);
      const b = 2 * m * h;
      const ans = m * h * h;
      return {
        content: `직선 $y=-${m}x+${b}$ 위에 있는 제$1$사분면 위의 점 $\\mathrm{P}$에서 $x$축, $y$축에 내린 수선의 발을 각각 $\\mathrm{Q}$, $\\mathrm{R}$라 할 때, 직사각형 $\\mathrm{OQPR}$의 넓이의 최댓값을 구하시오. (단, $\\mathrm{O}$는 원점이다.)`,
        answer: `$${ans}$`,
